const filas = $input.all().map(i => i.json);
const cupo = 10000;

// La fecha puede llegar como texto o como fecha, segun como haya quedado la hoja.
const dia = f => (f.fecha instanceof Date ? f.fecha.toISOString() : String(f.fecha)).slice(0, 10);

const ultimo = filas.reduce((m, f) => (dia(f) > m ? dia(f) : m), '');
const [anio, mes, diaTxt] = ultimo.split('-');
const delMes = filas.filter(f => dia(f).startsWith(`${anio}-${mes}`));
const usadas = delMes.reduce((s, f) => s + Number(f.ejecuciones), 0);
const diaDeHoy = Number(diaTxt);
const diasDelMes = new Date(Number(anio), Number(mes), 0).getDate();
const proyeccion = Math.round((usadas / diaDeHoy) * diasDelMes);

const porFlujo = {};
delMes.forEach(f => { porFlujo[f.flujo] = (porFlujo[f.flujo] || 0) + Number(f.ejecuciones); });
const principales = Object.entries(porFlujo).sort((a, b) => b[1] - a[1]).slice(0, 2)
  .map(([f, n]) => `${f}: ${n}`).join(' | ');

const porcentaje = Math.round((proyeccion / cupo) * 100);
const nivel = proyeccion > cupo ? 'urgente' : (proyeccion > 0.8 * cupo ? 'preventivo' : 'ok');

return [{ json: { usadas, dia: diaDeHoy, diasDelMes, proyeccion, porcentaje, nivel, principales } }];
